import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String s = line.trim();
        if (s.isEmpty()) return;
        long value = 0;
        for (int i = 0; i < s.length(); i++) {
            value = (value << 1) + (s.charAt(i) - '0');
        }
        System.out.println(value);
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null) return;
        String s = line.trim();
        if (s.isEmpty()) return;
        StringBuilder out = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            int j = i;
            while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
            out.append(s.charAt(i)).append(j - i);
            i = j;
        }
        System.out.println(out);
    }
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        if (line == null || line.trim().isEmpty()) return;
        String[] parts = line.trim().split(";");
        int h = Integer.parseInt(parts[0].trim()) % 12;
        int m = Integer.parseInt(parts[1].trim());
        double hourAngle = h * 30.0 + m * 0.5;
        double minuteAngle = m * 6.0;
        double diff = Math.abs(hourAngle - minuteAngle);
        double answer = Math.min(diff, 360.0 - diff);
        System.out.println(Math.round(answer));
    }
}
